'use client';

import type { BaseLayoutProps, NavOptions } from 'local:<dir>/shared/index.tsx';
import { type ComponentProps, createContext, type FC, use } from 'react';
import { baseSlots, useLinkItems, type BaseSlots, type BaseSlotsProps } from 'local:<dir>/shared/index.tsx';
import type { LinkItemType } from 'local:<dir>/shared/index.tsx';
import { Container } from 'local:<dir>/home/slots/container.tsx';
import { Header } from 'local:<dir>/home/slots/header.tsx';

export interface HomeLayoutProps extends BaseLayoutProps, ComponentProps<'main'> {
  nav?: Nav;
  slots?: Partial<HomeSlots>;
}

interface Nav extends NavOptions {
  /**
   * Open mobile menu when hovering the trigger
   */
  enableHoverToOpen?: boolean;
}

export interface HomeSlots extends BaseSlots {
  header: FC<ComponentProps<'header'>>;
  container: FC<ComponentProps<'main'>>;
}

const LayoutContext = createContext<{
  props: BaseSlotsProps<HomeLayoutProps>;
  navItems: LinkItemType[];
  menuItems: LinkItemType[];
  slots: HomeSlots;
} | null>(null);

export function useHomeLayout() {
  const context = use(LayoutContext);
  if (!context)
    throw new Error('Please use this component under <HomeLayout /> (`fumadocs-ui/layouts/home`).');
  return context;
}

const { useBaseSlots } = baseSlots({
  useProps() {
    return useHomeLayout().props;
  },
});

export function HomeLayout(props: HomeLayoutProps) {
  const {
    nav: { enabled: navEnabled = true } = {},
    slots: defaultSlots,
    children,
    i18n: _i18n,
    githubUrl: _githubUrl,
    links: _links,
    themeSwitch: _themeSwitch,
    searchToggle: _searchToggle,
    ...rest
  } = props;
  const { baseSlots, baseProps } = useBaseSlots(props);
  const linkItems = useLinkItems(props);
  const slots: HomeSlots = {
    ...baseSlots,
    header: defaultSlots?.header ?? Header,
    container: defaultSlots?.container ?? Container,
  };

  return (
    <LayoutContext
      value={{
        props: baseProps,
        slots,
        ...linkItems,
      }}
    >
      <slots.container {...rest}>
        {navEnabled && <slots.header />}
        {children}
      </slots.container>
    </LayoutContext>
  );
}

'use client';
import * as React from 'react';
import * as Primitive from '@radix-ui/react-navigation-menu';
import { cn } from 'local:utils/cn.ts';

export type NavigationMenuContentProps = Primitive.NavigationMenuContentProps;
export type NavigationMenuTriggerProps = Primitive.NavigationMenuTriggerProps;

export const NavigationMenu = Primitive.Root;

export const NavigationMenuList = Primitive.List;

export function NavigationMenuItem({
  className,
  children,
  ...props
}: React.ComponentProps<typeof Primitive.NavigationMenuItem>) {
  return (
    <Primitive.NavigationMenuItem className={cn('list-none', className)} {...props}>
      {children}
    </Primitive.NavigationMenuItem>
  );
}

export function NavigationMenuTrigger({
  className,
  children,
  ...props
}: React.ComponentProps<typeof Primitive.Trigger>) {
  return (
    <Primitive.Trigger className={cn('data-[state=open]:bg-fd-accent/50', className)} {...props}>
      {children}
    </Primitive.Trigger>
  );
}

export function NavigationMenuContent({
  className,
  ...props
}: React.ComponentProps<typeof Primitive.Content>) {
  return (
    <Primitive.Content
      className={cn(
        'absolute inset-x-0 top-0 overflow-auto fd-scroll-container max-h-[80svh] data-[motion=from-end]:animate-fd-enterFromRight data-[motion=from-start]:animate-fd-enterFromLeft data-[motion=to-end]:animate-fd-exitToRight data-[motion=to-start]:animate-fd-exitToLeft',
        className,
      )}
      {...props}
    />
  );
}

export const NavigationMenuLink = Primitive.Link;

export function NavigationMenuViewport({
  className,
  ref,
  ...props
}: React.ComponentProps<typeof Primitive.Viewport>) {
  return (
    <div ref={ref} className="flex w-full justify-center">
      <Primitive.Viewport
        {...props}
        className={cn(
          'relative h-(--radix-navigation-menu-viewport-height) w-full origin-[top_center] overflow-hidden transition-[width,height] duration-300 data-[state=closed]:animate-fd-nav-menu-out data-[state=open]:animate-fd-nav-menu-in',
          className,
        )}
      />
    </div>
  );
}
